// a.x hover, a.y press, a.z focus, a.w grain size in px
fn shade(px: Pixel) -> vec4<f32> {
  let wind = vec2<f32>(px.time * 6.0, px.time * 2.0);
  let size = max(px.a.w, 1.0);
  let grain = sd_noise((px.local + wind) / size) * 0.6 + sd_hash(floor(px.local / size)) * 0.4;
  var col = px.color.rgb * (0.88 + 0.2 * grain);
  let drift = sin(px.local.x * 0.03 - px.time * 1.2 + px.local.y * 0.01) * 0.5 + 0.5;
  col = col + vec3<f32>(0.10, 0.07, 0.03) * drift * (0.4 + px.a.x);
  let d = distance(px.local, px.pointer);
  col = col + vec3<f32>(1.0, 0.8, 0.5) * exp(-d * d / (2.0 * 70.0 * 70.0)) * (0.05 + 0.2 * px.a.x);
  let rim = smoothstep(-2.5, 0.0, px.sdf) * (0.25 + 0.3 * px.a.x + 0.3 * px.a.z);
  col = mix(col, vec3<f32>(0.98, 0.86, 0.62), rim);
  let kick = exp(-d * 0.02) * px.a.y * 0.14 * (0.5 + 0.5 * sin(d * 0.05 - px.time * 6.0));
  col = col - vec3<f32>(kick);
  return vec4<f32>(col, px.color.a);
}

