// engraved dial plate: hairline grid, major ticks, a sweeping gauge arc, crosshair at the pointer
fn shade(px: Pixel) -> vec4<f32> {
  var col = mix(vec3<f32>(0.075, 0.085, 0.10), vec3<f32>(0.05, 0.058, 0.07), px.uv.y);
  let g1 = abs(fract(px.local / 16.0 - vec2<f32>(0.5, 0.5)) - vec2<f32>(0.5, 0.5)) * 16.0;
  let minor = 1.0 - smoothstep(0.0, 0.7, min(g1.x, g1.y));
  let g2 = abs(fract(px.local / 80.0 - vec2<f32>(0.5, 0.5)) - vec2<f32>(0.5, 0.5)) * 80.0;
  let major = 1.0 - smoothstep(0.0, 0.9, min(g2.x, g2.y));
  col = col + vec3<f32>(0.55, 0.70, 0.78) * (minor * 0.035 + major * 0.09);
  let c = px.size * 0.5;
  let r = distance(px.local, c);
  let rad = min(px.size.x, px.size.y) * 0.42;
  let ring = 1.0 - smoothstep(0.0, 0.9, abs(r - rad));
  let ang = atan2(px.local.y - c.y, px.local.x - c.x);
  let sweep = fract((ang / 6.2831853) - px.time * 0.08);
  col = col + vec3<f32>(0.95, 0.62, 0.20) * ring * (0.10 + 0.5 * pow(1.0 - sweep, 6.0));
  let ticks = step(0.5, fract(ang * 36.0 / 6.2831853)) * (1.0 - smoothstep(0.0, 0.6, abs(r - rad * 0.94)));
  col = col + vec3<f32>(0.6, 0.72, 0.8) * ticks * 0.18;
  let cx = 1.0 - smoothstep(0.0, 0.8, abs(px.local.x - px.pointer.x));
  let cy = 1.0 - smoothstep(0.0, 0.8, abs(px.local.y - px.pointer.y));
  col = col + vec3<f32>(0.95, 0.62, 0.20) * (cx + cy) * 0.22 * exp(-distance(px.local, px.pointer) * 0.004);
  return vec4<f32>(col, 1.0);
}

