// a quiet eight-point star lattice over sand or night, fixed in place
fn shade(px: Pixel) -> vec4<f32> {
  let p = px.local / 72.0;
  let cell = fract(p) - vec2<f32>(0.5, 0.5);
  let ang = atan2(cell.y, cell.x);
  let r = length(cell);
  let star = abs(cos(ang * 4.0)) * 0.12 + 0.18;
  let ln = 1.0 - smoothstep(0.0, 0.02, abs(r - star));
  var col = mix(vec3<f32>(0.94, 0.89, 0.80), vec3<f32>(0.90, 0.83, 0.70), px.uv.y);
  col = mix(col, vec3<f32>(0.17, 0.29, 0.63), ln * 0.13);
  return vec4<f32>(col, 1.0);
}

// a glass card: a gold inlay line inside its edge and a faint star lattice that gathers in the corners
fn shade(px: Pixel) -> vec4<f32> {
  var col = px.color.rgb;
  let cell = fract(px.local / 48.0) - vec2<f32>(0.5, 0.5);
  let star = abs(cos(atan2(cell.y, cell.x) * 4.0)) * 0.12 + 0.2;
  let ln = 1.0 - smoothstep(0.0, 0.025, abs(length(cell) - star));
  let corner = 1.0 - smoothstep(0.0, 0.22, min(min(px.uv.x, 1.0 - px.uv.x), min(px.uv.y, 1.0 - px.uv.y)));
  col = mix(col, vec3<f32>(0.12, 0.31, 0.60), ln * (0.03 + 0.14 * corner));
  let inlay = 1.0 - smoothstep(0.3, 1.0, abs(px.sdf + 7.0));
  col = mix(col, vec3<f32>(0.72, 0.52, 0.11), inlay * 0.55);
  let d = distance(px.local, px.pointer);
  col = col + vec3<f32>(0.98, 0.82, 0.48) * exp(-d * d / 40000.0) * 0.05;
  return vec4<f32>(col, max(px.color.a, inlay * 0.55));
}

// a glazed zellige tile: lit from above, a gold inlay line inside its edge, a slow glint; a.x hover, a.y press, a.z focus
fn shade(px: Pixel) -> vec4<f32> {
  var col = px.color.rgb * (1.14 - 0.30 * px.uv.y);
  let d = distance(px.local, px.pointer);
  col = col + vec3<f32>(0.98, 0.82, 0.48) * exp(-d * d / 7000.0) * (0.04 + 0.16 * px.a.x);
  let inlay = 1.0 - smoothstep(0.35, 1.1, abs(px.sdf + 4.0));
  col = mix(col, vec3<f32>(0.72, 0.52, 0.11), inlay * (0.45 + 0.35 * px.a.x + 0.2 * px.a.z));
  let band = (px.local.x - px.local.y * 0.6) * 0.012 - px.time * 0.35;
  col = col + vec3<f32>(pow(max(0.0, sin(band)), 40.0) * 0.12);
  col = col * (1.0 - 0.14 * px.a.y);
  return vec4<f32>(col, max(px.color.a, inlay * 0.7));
}

