  let phase = ang + px.time * 0.02 + px.a.y * 0.3 + px.pointer.x / max(px.size.x, 1.0) * 0.12;
  let spec = pr_hue(phase);
  let rim = smoothstep(-1.6, -0.7, px.sdf);
  let glow = smoothstep(-10.0, 0.0, px.sdf) * (0.08 + 0.10 * px.a.x);
  let strength = clamp(0.72 + 0.28 * px.a.x, 0.0, 1.0);
  var col = px.color.rgb + spec * glow;
  col = mix(col, spec, rim * strength);
