// the moment night meets day: indigo into rose into apricot at the horizon, a thin luminous line, static film grain
fn dw_hash(p: vec2<f32>) -> f32 { return fract(sin(dot(p, vec2<f32>(127.1, 311.7))) * 43758.5453); }
fn dw_noise(p: vec2<f32>) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  return mix(mix(dw_hash(i), dw_hash(i + vec2<f32>(1.0, 0.0)), u.x), mix(dw_hash(i + vec2<f32>(0.0, 1.0)), dw_hash(i + vec2<f32>(1.0, 1.0)), u.x), u.y);
}
fn shade(px: Pixel) -> vec4<f32> {
  let indigo = vec3<f32>(0.110, 0.122, 0.290);
  let rose = vec3<f32>(0.784, 0.416, 0.494);
  let apricot = vec3<f32>(0.965, 0.725, 0.541);
  let dusk = vec3<f32>(0.42, 0.24, 0.35);
  let y = px.uv.y;
  var col = mix(indigo, rose, smoothstep(0.0, 0.42, y));
  col = mix(col, apricot, smoothstep(0.38, 0.65, y));
  col = mix(col, dusk, smoothstep(0.66, 1.0, y));
  let dy = abs(px.local.y - px.size.y * 0.65);
  let breath = 0.5 + 0.5 * sin(px.time * 0.25);
  col = col + vec3<f32>(1.0, 0.84, 0.55) * exp(-dy / 46.0) * (0.10 + 0.04 * breath);
  col = col + vec3<f32>(1.0, 0.94, 0.78) * (1.0 - smoothstep(0.0, 1.6, dy)) * 0.55;
  let g = dw_hash(floor(px.local)) - 0.5;
  col = col + vec3<f32>(g, g, g) * 0.045;
  return vec4<f32>(clamp(col, vec3<f32>(0.0, 0.0, 0.0), vec3<f32>(1.0, 1.0, 1.0)), 1.0);
}

// warm cream glass with a gold inlay line inside its edge; a.x hover, a.y press, a.z focus
fn shade(px: Pixel) -> vec4<f32> {
  var col = mix(px.color.rgb, vec3<f32>(0.99, 0.92, 0.84), px.uv.y * 0.35);
  let inlay = 1.0 - smoothstep(0.3, 1.0, abs(px.sdf + 5.0));
  col = mix(col, vec3<f32>(0.902, 0.761, 0.478), inlay * (0.5 + 0.3 * px.a.z));
  let d = distance(px.local, px.pointer);
  col = col + vec3<f32>(1.0, 0.85, 0.6) * exp(-d * d / 30000.0) * 0.05;
  return vec4<f32>(col, max(px.color.a, inlay * 0.5));
}

// a plum tile edged in gold, lit from the horizon; a.x hover, a.y press, a.z focus
fn shade(px: Pixel) -> vec4<f32> {
  var col = px.color.rgb * (1.12 - 0.22 * px.uv.y);
  let d = distance(px.local, px.pointer);
  col = col + vec3<f32>(1.0, 0.78, 0.55) * exp(-d * d / 6000.0) * (0.04 + 0.12 * px.a.x);
  let inlay = 1.0 - smoothstep(0.35, 1.1, abs(px.sdf + 3.5));
  col = mix(col, vec3<f32>(0.902, 0.761, 0.478), inlay * (0.35 + 0.35 * px.a.x));
  col = col * (1.0 - 0.14 * px.a.y);
