// manuscript paper: long fibres in two directions and a fine tooth, all static
fn ig_hash(p: vec2<f32>) -> f32 { return fract(sin(dot(p, vec2<f32>(127.1, 311.7))) * 43758.5453); }
fn ig_noise(p: vec2<f32>) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  return mix(mix(ig_hash(i), ig_hash(i + vec2<f32>(1.0, 0.0)), u.x), mix(ig_hash(i + vec2<f32>(0.0, 1.0)), ig_hash(i + vec2<f32>(1.0, 1.0)), u.x), u.y);
}
fn shade(px: Pixel) -> vec4<f32> {
  let p = px.local;
  let f1 = ig_noise(vec2<f32>(p.x * 0.9, p.y * 0.06));
  let f2 = ig_noise(vec2<f32>(p.y * 0.8 + 41.0, p.x * 0.05));
  let tooth = ig_hash(floor(p)) - 0.5;
  var col = vec3<f32>(0.957, 0.937, 0.894);
  col = col * (1.0 - 0.05 * f1 - 0.04 * f2);
  col = col + vec3<f32>(tooth, tooth, tooth) * 0.018;
  return vec4<f32>(clamp(col, vec3<f32>(0.0, 0.0, 0.0), vec3<f32>(1.0, 1.0, 1.0)), 1.0);
}

// gold leaf: a crinkled foil with a highlight that follows the pointer; a.x hover, a.y press, a.z focus
