// a sparse static star field and three slow ribbons of light that drift with time and bend toward the pointer
fn au_hash(p: vec2<f32>) -> f32 { return fract(sin(dot(p, vec2<f32>(127.1, 311.7))) * 43758.5453); }
fn au_noise(p: vec2<f32>) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  return mix(mix(au_hash(i), au_hash(i + vec2<f32>(1.0, 0.0)), u.x), mix(au_hash(i + vec2<f32>(0.0, 1.0)), au_hash(i + vec2<f32>(1.0, 1.0)), u.x), u.y);
}
fn au_ribbon(uv: vec2<f32>, pm: vec2<f32>, t: f32, k: f32) -> f32 {
  var y0 = 0.26 + 0.17 * k + 0.07 * sin(uv.x * (3.0 + k) + t * (2.0 + k) + k * 2.1) + 0.04 * sin(uv.x * 7.0 - t * 3.0 + k);
  let pull = exp(-(uv.x - pm.x) * (uv.x - pm.x) * 10.0);
  y0 = y0 + (pm.y - y0) * 0.30 * pull;
