  let cursor = step(px.size.x - 10.0, px.local.x) * step(px.local.x, px.size.x - 4.0) * step(4.0, px.local.y) * step(px.local.y, px.size.y - 4.0);
  col = col + vec3<f32>(0.3, 1.0, 0.5) * cursor * blink * px.a.z * 0.6;
  col = mix(col, vec3<f32>(0.4, 1.0, 0.6), px.a.y * 0.3);
  return vec4<f32>(col, px.color.a);
}

// slow aurora: three light pools drifting, a soft lamp where the pointer is
fn gl_blob(p: vec2<f32>, c: vec2<f32>, r: f32) -> f32 { let d = distance(p, c); return exp(-d * d / (r * r)); }
fn shade(px: Pixel) -> vec4<f32> {
  let t = px.time * 0.15;
  let s = px.size;
  var col = vec3<f32>(0.04, 0.05, 0.09);
  col = col + vec3<f32>(0.20, 0.35, 0.95) * gl_blob(px.local, s * vec2<f32>(0.3 + 0.15 * sin(t), 0.35 + 0.1 * cos(t * 1.3)), s.x * 0.45);
  col = col + vec3<f32>(0.75, 0.25, 0.85) * gl_blob(px.local, s * vec2<f32>(0.75 + 0.1 * cos(t * 0.8), 0.6 + 0.15 * sin(t * 1.1)), s.x * 0.4);
  col = col + vec3<f32>(0.15, 0.85, 0.75) * gl_blob(px.local, s * vec2<f32>(0.5 + 0.2 * sin(t * 0.6), 0.9), s.x * 0.35) * 0.6;
  let d = distance(px.local, px.pointer);
  col = col + vec3<f32>(0.25, 0.25, 0.25) * exp(-d * d / (2.0 * 200.0 * 200.0));
  return vec4<f32>(col, 1.0);
}

// a.x hover, a.y press, a.z focus
fn shade(px: Pixel) -> vec4<f32> {
  var col = px.color.rgb + vec3<f32>(0.10, 0.10, 0.10) * (1.0 - px.uv.y);
  let d = distance(px.local, px.pointer);
  col = col + vec3<f32>(1.0, 1.0, 1.0) * exp(-d * d / (2.0 * 60.0 * 60.0)) * (0.16 + 0.34 * px.a.x);
  let t = px.time * 0.6;
  col = col + vec3<f32>(0.04 * sin(px.local.x * 0.05 + t) * sin(px.local.y * 0.07 - t * 1.3));
  let rim = smoothstep(-2.5, 0.0, px.sdf);
  col = mix(col, vec3<f32>(1.0, 1.0, 1.0), rim * (0.45 + 0.4 * px.a.z));
  col = col * (1.0 - 0.12 * px.a.y * (1.0 - length(px.uv - vec2<f32>(0.5, 0.5))));
  return vec4<f32>(col, px.color.a * (0.55 + 0.25 * px.a.x + 0.2 * rim));
}

