// a.x hover, a.y press, a.z focus, a.w grain size in px
fn shade(px: Pixel) -> vec4<f32> {
  let wind = vec2<f32>(px.time * 6.0, px.time * 2.0);
  let size = max(px.a.w, 1.0);
