  let cy = 1.0 - smoothstep(0.0, 0.8, abs(px.local.y - px.pointer.y));
  col = col + vec3<f32>(0.95, 0.62, 0.20) * (cx + cy) * 0.22 * exp(-distance(px.local, px.pointer) * 0.004);
  return vec4<f32>(col, 1.0);
}

