fn shade(px: Pixel) -> vec4<f32> {
  let step_t = floor(px.time * 12.0);
  var col = vec3<f32>(0.01, 0.025, 0.015);
  let scan = 0.5 + 0.5 * sin(px.local.y * 3.14159265);
  col = col + vec3<f32>(0.0, 0.05, 0.02) * scan;
  let roll = fract(px.uv.y - step_t * 0.012);
  col = col + vec3<f32>(0.0, 0.07, 0.03) * smoothstep(0.9, 1.0, roll);
  let grain = tm_hash(px.local + vec2<f32>(step_t * 7.0, step_t * 3.0));
  col = col + vec3<f32>(0.0, 0.03, 0.01) * grain;
  let flick = 0.96 + 0.04 * tm_hash(vec2<f32>(step_t, 1.0));
  let v = px.uv - vec2<f32>(0.5, 0.5);
  col = col * flick * (1.0 - dot(v, v) * 0.9);
  let d = distance(px.local, px.pointer);
  col = col + vec3<f32>(0.15, 0.9, 0.4) * exp(-d * d / (2.0 * 90.0 * 90.0)) * 0.10;
  return vec4<f32>(col, 1.0);
