// white light parted into faint slow caustic bands and gathered back to white; the hue phase follows the pointer
fn pr_hue(h: f32) -> vec3<f32> {
  let k = vec3<f32>(1.0, 0.6667, 0.3333);
  return clamp(abs(fract(vec3<f32>(h) + k) * 6.0 - vec3<f32>(3.0, 3.0, 3.0)) - vec3<f32>(1.0, 1.0, 1.0), vec3<f32>(0.0, 0.0, 0.0), vec3<f32>(1.0, 1.0, 1.0));
}
fn shade(px: Pixel) -> vec4<f32> {
  let sz = vec2<f32>(max(px.size.x, 1.0), max(px.size.y, 1.0));
  let q = px.local / sz.x;
  let pm = px.pointer / sz;
  let t = px.time * 0.03;
  let w = q.x * 1.1 + q.y * 0.7 + 0.35 * sin(q.y * 5.0 + t * 6.0) + 0.25 * sin(q.x * 3.0 - t * 4.0);
  let band = 0.5 + 0.5 * sin(w * 9.0 + t * 8.0);
  let spec = pr_hue(fract(w * 0.35 + t + pm.x * 0.25 + pm.y * 0.15));
  var col = vec3<f32>(0.969, 0.965, 0.949);
  col = mix(col, spec, 0.05 * band);
  col = col + vec3<f32>(0.018, 0.018, 0.018) * (1.0 - band);
  return vec4<f32>(clamp(col, vec3<f32>(0.0, 0.0, 0.0), vec3<f32>(1.0, 1.0, 1.0)), 1.0);
}

// frosted white glass edged by a hairline of the whole spectrum, hue by angle around the shape; a.x hover, a.y press (turns the hue), a.z focus
fn pr_hue(h: f32) -> vec3<f32> {
  let k = vec3<f32>(1.0, 0.6667, 0.3333);
  return clamp(abs(fract(vec3<f32>(h) + k) * 6.0 - vec3<f32>(3.0, 3.0, 3.0)) - vec3<f32>(1.0, 1.0, 1.0), vec3<f32>(0.0, 0.0, 0.0), vec3<f32>(1.0, 1.0, 1.0));
}
fn shade(px: Pixel) -> vec4<f32> {
  let c = px.uv - vec2<f32>(0.5, 0.5);
  let ang = atan2(c.y, c.x) / 6.2831853 + 0.5;
  let phase = ang + px.time * 0.02 + px.a.y * 0.3 + px.pointer.x / max(px.size.x, 1.0) * 0.12;
  let spec = pr_hue(phase);
  let rim = smoothstep(-1.6, -0.7, px.sdf);
  let strength = clamp(0.78 + 0.22 * px.a.x, 0.0, 1.0);
  let lit = min(spec * (1.0 + 0.25 * px.a.x), vec3<f32>(1.0, 1.0, 1.0));
  var col = mix(px.color.rgb, spec, 0.03 * (1.0 - rim));
  col = mix(col, lit, rim * strength);
  return vec4<f32>(col, max(px.color.a, rim * strength));
}

