// a sparse static star field and three slow ribbons of light that drift with time and bend toward the pointer
fn au_hash(p: vec2<f32>) -> f32 { return fract(sin(dot(p, vec2<f32>(127.1, 311.7))) * 43758.5453); }
fn au_noise(p: vec2<f32>) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  return mix(mix(au_hash(i), au_hash(i + vec2<f32>(1.0, 0.0)), u.x), mix(au_hash(i + vec2<f32>(0.0, 1.0)), au_hash(i + vec2<f32>(1.0, 1.0)), u.x), u.y);
}
fn au_ribbon(uv: vec2<f32>, pm: vec2<f32>, t: f32, k: f32) -> f32 {
  var y0 = 0.26 + 0.17 * k + 0.07 * sin(uv.x * (3.0 + k) + t * (2.0 + k) + k * 2.1) + 0.04 * sin(uv.x * 7.0 - t * 3.0 + k);
  let pull = exp(-(uv.x - pm.x) * (uv.x - pm.x) * 10.0);
  y0 = y0 + (pm.y - y0) * 0.30 * pull;
  let d = uv.y - y0;
  let fall = exp(-d * d * 55.0);
  let curtain = 0.6 + 0.4 * sin(uv.x * 11.0 + k * 3.0 + t * 4.0);
  return fall * curtain;
}
fn shade(px: Pixel) -> vec4<f32> {
  let sz = vec2<f32>(max(px.size.x, 1.0), max(px.size.y, 1.0));
  let uv = px.local / sz;
  let pm = px.pointer / sz;
  let t = px.time * 0.05;
  var col = mix(vec3<f32>(0.020, 0.035, 0.080), vec3<f32>(0.027, 0.043, 0.094), uv.y);
  let cell = floor(px.local / 3.0);
  let h = au_hash(cell);
  let star = step(0.9985, h) * (0.5 + 0.5 * au_hash(cell + vec2<f32>(7.0, 3.0)));
  let green = au_ribbon(uv, pm, t, 0.0);
  let violet = au_ribbon(uv, pm, t * 0.8 + 1.7, 1.0);
  let teal = au_ribbon(uv, pm, t * 1.2 + 3.1, 2.0);
  col = col + vec3<f32>(0.36, 0.95, 0.69) * green * 0.20;
  col = col + vec3<f32>(0.56, 0.42, 1.0) * violet * 0.18;
  col = col + vec3<f32>(0.22, 0.77, 0.84) * teal * 0.16;
  col = col + vec3<f32>(0.8, 0.85, 1.0) * star * 0.8 * (1.0 - clamp(green + violet + teal, 0.0, 1.0) * 0.6);
  return vec4<f32>(clamp(col, vec3<f32>(0.0, 0.0, 0.0), vec3<f32>(1.0, 1.0, 1.0)), 1.0);
}

// dark frosted glass with a cool hairline rim and a faint sheen of the ribbons; a.x hover, a.y press, a.z focus
fn shade(px: Pixel) -> vec4<f32> {
  let rim = smoothstep(-1.8, -0.6, px.sdf);
  let sheen = 0.5 + 0.5 * sin(px.local.x * 0.01 + px.time * 0.1 + px.local.y * 0.006);
  var col = px.color.rgb + mix(vec3<f32>(0.36, 0.95, 0.69), vec3<f32>(0.56, 0.42, 1.0), sheen) * (0.025 + 0.02 * px.a.x);
  col = mix(col, vec3<f32>(0.55, 0.85, 0.95), rim * (0.30 + 0.25 * px.a.x + 0.3 * px.a.z));
  return vec4<f32>(col, max(px.color.a, rim * 0.4));
}

