fn nq_hash(p: vec2<f32>) -> f32 { return fract(sin(dot(p, vec2<f32>(127.1, 311.7))) * 43758.5453); }
fn nq_noise(p: vec2<f32>) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  return mix(mix(nq_hash(i), nq_hash(i + vec2<f32>(1.0, 0.0)), u.x), mix(nq_hash(i + vec2<f32>(0.0, 1.0)), nq_hash(i + vec2<f32>(1.0, 1.0)), u.x), u.y);
}
// a.x hover, a.y press, a.z focus, a.w grain size in px
fn shade(px: Pixel) -> vec4<f32> {
  let drift = vec2<f32>(px.time * 3.0, px.time * 1.3);
  let size = max(px.a.w, 1.0);
  let grain = 0.5 * nq_noise((px.local + drift) / size) + 0.5 * nq_noise((px.local - drift * 0.5) / (size * 0.37));
  var col = px.color.rgb * (0.9 + 0.14 * grain);
